import { ErrorBoundary, Suspense } from '@suspensive/react';
import { useRef, useCallback } from 'react';
import { FallbackErrorMessage } from '~/widgets/fallbacks/ui/fallback-error-message';
import { LoadingSpinner } from '~/widgets/loading/loading-spinner';
import { overlay } from '~/shared/lib/overlay';
import { BottomSheet } from '~/shared/ui/bottom-sheets/bottom-sheet';
import {
  BaseSelectList,
  SelectStyle,
  SelectBottomSheetProps,
  SelectConfirmProps,
  LabelChangeProps,
} from '~/shared/ui/selects';

export const useSelectBottomSheet = <T,>() => {
  const currentPropsRef = useRef<SelectBottomSheetProps<T> | null>(null);
  const unmountRef = useRef<(() => void) | null>(null);

  const handleClose = useCallback(() => {
    currentPropsRef.current?.onClose?.();
    overlay.closeAll();
  }, []);

  const openSelectBottomSheet = (selectBottomSheet: SelectBottomSheetProps<T>) => {
    const getBottomSheetContent = (isOpen: boolean) => {
      const {
        options,
        selectedOption: currentSelectedOption,
        valueKey,
        title = '',
        description = '',
        selectStyle = SelectStyle.DEFAULT,
        shouldShowConfirmButton = false,
        confirmButtonLabel,
        onConfirm,
        onClose,
      } = currentPropsRef.current || selectBottomSheet;

      const handleLabelChange = ({ event, option }: LabelChangeProps<T>) => {
        if (currentPropsRef.current) {
          currentPropsRef.current = {
            ...currentPropsRef.current,
            selectedOption: option,
          };
        }
        selectBottomSheet?.onRadioChange?.({ event, option });
      };

      const handleConfirm = ({ event, selectedOption }: SelectConfirmProps<T>, close: () => void) => {
        onConfirm?.({ event, selectedOption });
        onClose?.();
        close();
      };

      return (
        <ErrorBoundary fallback={FallbackErrorMessage}>
          <Suspense fallback={<LoadingSpinner />}>
            <BottomSheet
              title={title}
              afterLeave={() => unmountRef.current?.()}
              open={isOpen}
              onClose={handleClose}
            >
              <BaseSelectList
                description={description}
                options={options}
                selectedOption={currentSelectedOption}
                valueKey={valueKey}
                onLabelChange={handleLabelChange}
                selectStyle={selectStyle}
                shouldShowConfirmButton={shouldShowConfirmButton}
                confirmButtonLabel={confirmButtonLabel}
                onConfirm={(props) => handleConfirm(props, overlay.closeAll)}
              />
            </BottomSheet>
          </Suspense>
        </ErrorBoundary>
      );
    };

    if (unmountRef.current) {
      unmountRef.current();
      unmountRef.current = null;
    }

    currentPropsRef.current = selectBottomSheet;

    overlay.exclusiveOpen(({ isOpen, unmount, close }) => {
      unmountRef.current = unmount;
      return getBottomSheetContent(isOpen);
    });
  };

  return {
    openSelectBottomSheet,
    closeBottomSheet: handleClose,
  };
};
